from pathlib import Path
p=Path(__file__).resolve().parent;data=p/'data';data.mkdir(exist_ok=True)
states=[line.replace('|',' ').split()for line in(p/'large.bits').read_text().splitlines()]
for n in [0,1,2,3,6,16,100]:
 (data/(str(n)+'.positions')).write_text(''.join(row[0].zfill(8)+'\n'for row in states[:n]))
(data/'states.data').write_text(''.join(' '.join(row)+'\n'for row in states[:16]))
bad=int(states[0][0],16)^1;(data/'wrong.positions').write_text(format(bad,'08x')+'\n')
lines=['structure NeedAtom=BenchAtomFn(BenchNeed)','structure StrictAtom=BenchAtomFn(BenchStrict)','structure NeedDriver=BenchAtomDriverFn(NeedAtom)','structure StrictDriver=BenchAtomDriverFn(StrictAtom)','structure AtomTests =','struct','  structure N=NeedAtom','  structure R=StrictAtom','  structure L=BenchLazy','  structure S=BenchStream','  fun read name=let val f=TextIO.openIn name val data=TextIO.inputAll f val _=TextIO.closeIn f in data end','  fun word s=case Word32.fromString s of SOME n=>n|NONE=>raise Fail "invalid bits"','  fun expected n=Vector.fromList(List.map word(String.tokens Char.isSpace(read(Int.toString n^".positions"))))','  fun vectorN xs=(case BenchNeed.force xs of N.Nil=>[]|N.Cons(x,xs)=>N.bits(BenchNeed.force x)::vectorN xs)','  fun vectorR xs=(case BenchStrict.force xs of R.Nil=>[]|R.Cons(x,xs)=>R.bits(BenchStrict.force x)::vectorR xs)','  fun stateN value=let val N.State(p,v)=L.force value in(vectorN p,vectorN v)end','  fun stateR value=let val R.State(p,v)=L.force value in(vectorR p,vectorR v)end','  fun firstN 0 states=[]|firstN n states=(case L.force states of S.Nil=>raise Empty|S.Cons(value,rest)=>stateN value::firstN(n-1)rest)','  fun firstR 0 states=[]|firstR n states=(case L.force states of S.Nil=>raise Empty|S.Cons(value,rest)=>stateR value::firstR(n-1)rest)','  val stateExpected=List.map(fn line=>case String.tokens Char.isSpace line of [p,v]=>([word p],[word v])|_=>raise Fail "state tuple")(String.tokens(fn c=>Char.ord c=10)(read "states.data"))']
probe=(p/'counter.sml').read_text();body=probe.split('  fun observeN',1)[1].split('  val _=List.app',1)[0];lines.append('  fun observeN'+body)
for n in [0,1,2,3,6,16,100]:
 h=0x811c9dc5
 for row in states[:n]:h=((h^int(row[0],16))*0x01000193)&0xffffffff
 for mode,k,driver in [('lazy','N','NeedDriver'),('strict','R','StrictDriver')]:
  lines.append(f'  val _=T.check("atom/{mode}-position-prefix-{n}",fn()=>{k}.run {n}(expected {n})="{n}:{h:X}")')
for n in range(7):
 a=0 if n<2 else (n-1)*(n-2)//2;b=n*(n-1)//2
 lines.append(f'  val _=T.check("atom/unshared-lazy-force-count-{n}",fn()=>observeN {n}={a})')
 lines.append(f'  val _=T.check("atom/unshared-strict-force-count-{n}",fn()=>observeR {n}={b})')
lines+=['  val _=T.check("atom/lazy-full-state-bits",fn()=>firstN 16(N.start())=stateExpected)','  val _=T.check("atom/strict-full-state-bits",fn()=>firstR 16(R.start())=stateExpected)','  val _=T.check("atom/lazy-positions-do-not-demand-unused-force",fn()=>','    let fun bad _ stream=S.map(fn _=>raise Fail "force demanded")stream','        val stream=N.experiment bad N.dt(N.fromList[1.0])(L.delay(fn()=>N.State(N.fromList[1.0],N.fromList[0.0])))','        fun positions 0 _=()|positions n stream=(case L.force stream of S.Nil=>raise Empty|S.Cons(value,rest)=>','          let val N.State(p,_)=L.force value val _=vectorN p in positions(n-1)rest end)','    in positions 2 stream;true end)','  val _=T.check("atom/next-position-demands-force",fn()=>','    let fun bad _ stream=S.map(fn _=>raise Fail "force demanded")stream','        val stream=N.experiment bad N.dt(N.fromList[1.0])(L.delay(fn()=>N.State(N.fromList[1.0],N.fromList[0.0])))','        fun positions 0 _=()|positions n stream=(case L.force stream of S.Nil=>raise Empty|S.Cons(value,rest)=>','          let val N.State(p,_)=L.force value val _=vectorN p in positions(n-1)rest end)','    in ((positions 3 stream;false)handle Fail s=>s="force demanded")end)','  val _=T.check("atom/source-vector-multiply-right-tail-square",fn()=>','    vectorN(N.multiply(N.fromList[1.0,3.0])(N.fromList[2.0,4.0]))=[0wx40000000,0wx41800000])','  val _=T.check("atom/source-force-two-dimensions",fn()=>','    let val initial=L.delay(fn()=>N.State(N.fromList[1.0,2.0],N.fromList[0.0,0.0]))','        val law=N.forceLaw(N.fromList[1.0,3.0])(S.cons(initial,S.empty()))','        val force=case L.force law of S.Cons(value,_)=>value|_=>raise Empty','        val propagated=L.delay(fn()=>N.propagate N.dt force initial)','    in vectorN(L.force force)=[0wxBF800000,0wx40800000]andalso','       stateN propagated=([0wx3F800000,0wx40000000],[0wxBCA3D70A,0wx3DA3D70A])end)','  val _=T.check("atom/multiply-ignores-left-tail",fn()=>','    let val left=BenchNeed.delay(fn()=>N.Cons(BenchNeed.delay(fn()=>1.0),BenchNeed.delay(fn()=>raise Fail "unused left tail")))','    in vectorN(N.multiply left(N.fromList[2.0,3.0]))=[0wx40000000,0wx41100000]end)','  val _=T.check("atom/multiply-right-empty-does-not-demand-left",fn()=>case BenchNeed.force(N.multiply(BenchNeed.delay(fn()=>raise Fail "unused vector"))(N.empty()))of N.Nil=>true|_=>false)','  val _=T.check("atom/add-reuses-longer-tail-head",fn()=>','    let val right=N.fromList[2.0,3.0]val added=N.add(N.fromList[1.0])right','        fun second xs=case BenchNeed.force xs of N.Cons(_,rest)=>(case BenchNeed.force rest of N.Cons(value,_)=>value|_=>raise Empty)|_=>raise Empty','    in second right=second added end)','  val _=T.check("atom/binary32-positive-zero",fn()=>N.bits 0.0=0w0)','  val _=T.check("atom/binary32-negative-zero",fn()=>N.bits(~0.0)=0wx80000000)','  val _=T.check("atom/binary32-tie-to-even-low",fn()=>N.bits(BenchMandelSingle.round(1.0+Math.pow(2.0,~24.0)))=0wx3F800000)','  val _=T.check("atom/binary32-tie-to-even-high",fn()=>N.bits(BenchMandelSingle.round(1.0+3.0*Math.pow(2.0,~24.0)))=0wx3F800002)','  val _=T.check("atom/helper-rejects-subnormal-domain",fn()=>((BenchMandelSingle.round 1.0E~40;false)handle Domain=>true))','  val _=T.check("atom/rejects-non-binary32-input",fn()=>((N.bits(1.0+1.0E~10);false)handle Fail s=>String.isPrefix "incorrect result:" s))','  val _=T.check("atom/rejects-nonfinite",fn()=>((N.bits Real.posInf;false)handle Fail s=>String.isPrefix "incorrect result:" s))']
for mode,k in [('lazy','N'),('strict','R')]:
 lines.append(f'  val _=T.check("atom/{mode}-reject-wrong-position",fn()=>(({k}.run 1(Vector.fromList(List.map word(String.tokens Char.isSpace(read "wrong.positions"))));false)handle Fail s=>String.isPrefix "incorrect result:" s))')
 lines.append(f'  val _=T.check("atom/{mode}-reject-short-reference",fn()=>(({k}.run 2(expected 1);false)handle Fail s=>String.isPrefix "incorrect result:" s))')
 lines.append(f'  val _=T.check("atom/{mode}-reject-extra-reference",fn()=>(({k}.run 1(expected 2);false)handle Fail s=>String.isPrefix "incorrect result:" s))')
lines+=['end']
(p/'tests.sml').write_text('\n'.join(lines)+'\n');(p/'test-data.txt').write_text(''.join(f.name+'\n'for f in sorted(data.iterdir())if f.is_file()));root=Path.cwd();files=['tests/basis/harness.sml','examples/benchmarks/shared/input.sml','examples/benchmarks/shared/lazy.sml','examples/benchmarks/shared/suspend.sml','examples/benchmarks/shared/stream.sml','examples/benchmarks/shared/finite-binary32.sml',str(p/'kernel.sml'),str(p/'driver.sml'),str(p/'tests.sml'),'tests/basis/finish.sml'];(p/'test-sources.txt').write_text(''.join(str(root/f)+'\n'for f in files))
